use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut intervals = Vec::new();
    for interval in input.as_array() {
        let start = interval[0].as_i64().unwrap();
        let end = interval[1].as_i64().unwrap();
        intervals.push((start, end));
    }

    intervals.sort_unstable_by(|a, b| a.0.cmp(&b.0));

    let mut result = Vec::new();
    let mut current_start = None;
    let mut current_end = None;

    for interval in intervals {
        if current_start.is_none() {
            current_start = Some(interval.0);
        } else if interval.0 > current_end {
            result.push((current_start.unwrap(), current_end.unwrap()));
            current_start = Some(interval.0);
        }
    }

    if current_start.is_some() {
        result.push((current_start.unwrap(), current_end.unwrap()));
    }

    serde_json::Value::from(result)
}
